    if e: return False, e
    f = ns["is_fake"]
    if not callable(f):
        return False, "`is_fake` should be a function (def is_fake(review): ...)."
    tests = [
        ({"stars": "5", "text": "BEST product ever!!"}, True),
        ({"stars": "4", "text": "best product ever"}, False),
